SELECT jsonb_build_object('functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname||'.'||p.proname IN('twuanis_canonical_private.s3_command','twuanis_canonical_private.s3_decimal','twuanis_canonical_private.s3_geography','twuanis_canonical_private.s3_keys','twuanis_canonical_private.s3_origins','twuanis_canonical_private.s3_seal_classification','twuanis_canonical_private.s3_sealed_rule_guard','twuanis_canonical_private.s3_term_ids')),'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.oid::regclass::text,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'acl',c.relacl,'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)) ORDER BY c.oid::regclass::text) FROM pg_class c WHERE c.oid IN('twuanis_canonical_private.accessibility_identity'::regclass,'twuanis_canonical_private.classification_seals'::regclass)));
